agent_detail.agent_sql:
SELECT ?bond_type WHERE {
  ?b a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
}
GROUP BY ?bond_type
ORDER BY DESC(COUNT(?b))
LIMIT 1

SELECT DISTINCT ?molecule_id WHERE {
  ?m a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?molecule_id ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> ?label .
  FILTER(?label = "+")
  ?b a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/molecule_id> ?molecule_id ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
  FILTER(?bond_type = "#")
}

SELECT ?label WHERE {
  ?a a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> ?element ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/hasMolecule> ?m .
  ?m <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> ?label .
  FILTER(LCASE(STR(?element)) = "h")
}
GROUP BY ?label
ORDER BY DESC(COUNT(?a))
LIMIT 1

SELECT DISTINCT ?element WHERE {
  ?c a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/bond_id> "TR004_8_9" ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/hasAtom> ?a .
  ?a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> ?element .
}

SELECT (AVG(?cnt) AS ?avgBonds)
WHERE {
  SELECT ?m (COUNT(?b) AS ?cnt)
  WHERE {
    ?mol a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule> ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> "+" ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?m .
    ?b a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
       <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/molecule_id> ?m ;
       <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> "-" .
  }
  GROUP BY ?m
}

SELECT (SUM(IF(?element = "c", 1, 0)) * 100.0 / COUNT(?atom_id) AS ?pct)
WHERE {
  {
    SELECT DISTINCT ?mid WHERE {
      ?b a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> "=" ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/molecule_id> ?mid .
    }
  }
  ?a a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/molecule_id> ?mid ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> ?element ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/atom_id> ?atom_id .
}

SELECT ?bond_type WHERE {
  ?c a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/atom_id> "TR004_8" ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/atom_id2> "TR004_20" ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/bond_id> ?bondId .
  ?b a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_id> ?bondId ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
}

SELECT (COUNT(*) AS ?n) WHERE {
  ?atom a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> ?element ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/molecule_id> ?molId .
  FILTER(?element IN ("i", "s"))
  ?bond a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/molecule_id> ?molId ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> "-" .
}

SELECT ((SUM(IF(?el = "o", 1, 0)) * 1.0) / COUNT(DISTINCT ?m) AS ?avgOxygen)
WHERE {
  ?atom a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/molecule_id> ?m ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> ?el .
  ?bond a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/molecule_id> ?m ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> ?bt .
  FILTER(?bt = "-")
}

SELECT ?element WHERE {
  {
    SELECT ?element (COUNT(?atom) AS ?cnt) WHERE {
      ?atom a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
            <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/molecule_id> "TR000" ;
            <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> ?element .
    }
    GROUP BY ?element
    ORDER BY DESC(?cnt)
    LIMIT 3
  }
}
ORDER BY ?element

SELECT ((SUM(IF(?bt = "=", 1, 0)) / COUNT(?b)) * 100 AS ?percentage)
WHERE {
  ?b a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/molecule_id> "TR008" ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> ?bt .
}

SELECT ?element WHERE {
  ?m a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> "-" ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?mid .
  ?a a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/molecule_id> ?mid ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> ?element .
}
GROUP BY ?element
ORDER BY COUNT(?a)
LIMIT 1

SELECT ((SUM(IF(?label = "+", 1, 0)) * 100.0) / COUNT(?m) AS ?percentage)
WHERE {
  ?m a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> ?label .
}

SELECT ?element ?label WHERE {
  ?m a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/molecule_id> "TR060" ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> ?label .
  ?a a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/molecule_id> "TR060" ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> ?element .
}

SELECT DISTINCT ?molecule_id WHERE {
  ?m a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?molecule_id ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> ?label .
  FILTER(?label = "-")
  ?b a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/molecule_id> ?molecule_id ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
  FILTER(?bond_type = "-")
}
ORDER BY ?molecule_id
LIMIT 3

SELECT ?bond_type ?label WHERE {
  {
    SELECT ?bond_type (COUNT(?b) AS ?cnt) WHERE {
      ?b a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/molecule_id> "TR010" ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
    }
    GROUP BY ?bond_type
    ORDER BY DESC(?cnt)
    LIMIT 1
  }
  ?m a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/molecule_id> "TR010" ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> ?label .
}

SELECT (xsd:decimal(?carc) / xsd:decimal(?total) * 100 AS ?percentage)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?m) AS ?carc) WHERE {
      ?m a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule> ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> "+" .
      ?b a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/hasMolecule> ?m ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> "#" .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?m2) AS ?total) WHERE {
      ?b2 a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
          <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/hasMolecule> ?m2 ;
          <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> "#" .
    }
  }
}

SELECT (COUNT(DISTINCT ?bond) AS ?n) WHERE {
  ?b a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_id> ?bond ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/molecule_id> "TR009" .
  ?c a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/bond_id> ?bond .
  { ?c <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/atom_id> "TR009_12" }
  UNION
  { ?c <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/atom_id2> "TR009_12" }
}

SELECT (COUNT(*) AS ?n) WHERE {
  ?c a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/atom_id> "19" .
}

SELECT ?bond_type ?atom_id ?atom_id2 WHERE {
  ?bond a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_id> "TR001_6_9" ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
  ?conn a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected> ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/bond_id> "TR001_6_9" ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/atom_id> ?atom_id ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/atom_id2> ?atom_id2 .
}

SELECT ?element WHERE {
  ?atom a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/molecule_id> "TR004" ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> ?element .
}

SELECT DISTINCT ?molecule_id WHERE {
  ?atom a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/atom_id> ?atom_id ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/hasMolecule> ?mol .
  ?mol a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule> ;
       <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?molecule_id ;
       <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> ?label .
  FILTER(?label = "+")
  BIND(STRAFTER(STR(?atom_id), "_") AS ?ordinalStr)
  FILTER(xsd:integer(?ordinalStr) >= 21 && xsd:integer(?ordinalStr) <= 25)
}

SELECT DISTINCT ?bond_id WHERE {
  ?c a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/atom_id> ?a1id ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/atom_id2> ?a2id ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/bond_id> ?bond_id .
  ?a1 a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
      <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/atom_id> ?a1id ;
      <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> ?e1 .
  ?a2 a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
      <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/atom_id> ?a2id ;
      <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> ?e2 .
  FILTER(
    (LCASE(?e1) = "p" && LCASE(?e2) = "n") ||
    (LCASE(?e1) = "n" && LCASE(?e2) = "p")
  )
}

SELECT ?label WHERE {
  {
    SELECT ?molecule_id (COUNT(?bond) AS ?cnt) WHERE {
      ?bond a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
            <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/molecule_id> ?molecule_id ;
            <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> ?bt .
      FILTER(?bt = "=")
    }
    GROUP BY ?molecule_id
    ORDER BY DESC(?cnt)
    LIMIT 1
  }
  ?m a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?molecule_id ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> ?label .
}

SELECT (ROUND((xsd:decimal(?hcount) / xsd:decimal(?total)) * 100 * 10000) / 10000 AS ?percentage)
WHERE {
  {
    SELECT (COUNT(?a) AS ?hcount) WHERE {
      ?a a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/molecule_id> "TR206" ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> "h" .
    }
  }
  {
    SELECT (COUNT(?b) AS ?total) WHERE {
      ?b a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/molecule_id> "TR206" .
    }
  }
}

SELECT (AVG(?bondCount) AS ?avgBonds)
WHERE {
  {
    SELECT ?atom (COUNT(?conn) AS ?bondCount) WHERE {
      ?atom a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
            <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> "i" ;
            <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/atom_id> ?atomId .
      ?conn a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected> ;
            <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/atom_id> ?atomId .
    }
    GROUP BY ?atom
  }
}

SELECT DISTINCT ?element WHERE {
  ?atom a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/atom_id> ?atom_id ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> ?element .
  FILTER NOT EXISTS {
    ?c a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected> ;
       <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/atom_id> ?atom_id .
  }
  FILTER NOT EXISTS {
    ?c2 a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected> ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/atom_id2> ?atom_id .
  }
}

SELECT ?atom_id ?atom_id2 WHERE {
  ?bond a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/molecule_id> "TR041" ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> "#" ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_id> ?bond_id .
  ?conn a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected> ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/bond_id> ?bond_id ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/atom_id> ?atom_id ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/atom_id2> ?atom_id2 .
}

SELECT ?element WHERE {
  ?c a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected> ;
